    table = new_table(2)
    order = []
    for value in values:
        found = table_get(table, value)
        if found[0]:
            hash_put(table, value, found[1] + 1)
        else:
            hash_put(table, value, 1)
            order.append(value)
    result = []
    for value in order:
        result.append([value, table_get(table, value)[1]])
    return result

